enum Status { Stopped, Running, Failed }

IShape s = new Square(3);
Console.WriteLine(s.Area());

interface IShape { double Area(); }
class Square(double side) : IShape { public double Area() => side * side; }

int score = 82;
string grade = score switch
{
    >= 90 => "A",
    >= 80 => "B",
    _ => "C"
};
Console.WriteLine(grade);

var (min, max) = MinMax(new[] { 3, 9, 1 });
Console.WriteLine($"{min} {max}");

static (int, int) MinMax(int[] xs) => (xs.Min(), xs.Max());

var ages = new Dictionary<string, int> { ["Ann"] = 31, ["Bo"] = 25 };
if (ages.TryGetValue("Ann", out var age))
    Console.WriteLine(age);

var seen = new HashSet<string>();
foreach (var w in "a b a c".Split(' '))
    if (!seen.Add(w)) Console.WriteLine($"duplicate: {w}");

var names = new[] { "Cy", "Ann", "Bo" };
foreach (var n in names.OrderBy(n => n))
    Console.WriteLine(n);

var words = "the cat and the hat".Split(' ');
foreach (var g in words.GroupBy(w => w))
    Console.WriteLine($"{g.Key}: {g.Count()}");

